from concurrent.futures import ThreadPoolExecutor

class UnitOfWork:
    def __init__(self, metadata=None, timeout=None):
        self.metadata = metadata
        self.timeout = timeout

    async def __call__(self, coro):
        async with ThreadPoolExecutor() as executor:
            if self.timeout:
                result = await asyncio.wait_for(self._execute(coro, executor), timeout=self.timeout)
            else:
                result = await self._execute(coro, executor)
        return result

    def _execute(self, coro, executor):
        if self.metadata:
            executor.submit_async(coro, metadata=self.metadata)
        else:
            executor.submit_async(coro)
