from neo4j import Transaction, AsyncTransaction

class UnitOfWork:
    def __init__(self, metadata=None, timeout=None):
        self.metadata = metadata
        self.timeout = timeout

    @staticmethod
    def decorate(func):
        async def wrapper(*args, **kwargs):
            with Transaction() as tx:
                if self.metadata:
                    tx.metadata = self.metadata
                if self.timeout:
                    tx.timeout = self.timeout
                await func(tx, *args, **kwargs)
        return wrapper

    def execute(self, tx, func, *args, **kwargs):
        if self.timeout:
            tx.database.execute("CALL dbms.setTXMetaData({{\"query\": \"{query}\", \"metadata\": {\"timeout\": {timeout}}}})".format(query=func.__qualname__, timeout=self.timeout))
        else:
            tx.database.execute("CALL dbms.setTXMetaData({{\"query\": \"{query}\", \"metadata\": {}}}})".format(func.__qualname__, {}))
        return func(tx, *args, **kwargs)
