def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                     are provided, all values will be included
    :rtype: list
    """
    if not self._records:
        raise ValueError("Record is empty")

    if not keys:
        return list(self._records.values())

    values = []
    for index, key in enumerate(keys):
        if index < len(self._records.values()):
            if isinstance(key, int):
                # Assuming key is an integer index
                values.append(self._records.values()[key])
            elif isinstance(key, str):
                # Assuming key is a string key
                if key in self._records.keys():
                    values.append(self._records[key])
                else:
                    raise ValueError(f"Key '{key}' not found in the record")
        else:
            raise IndexError(f"Index out of range: {index}")

    return values
