from collections import OrderedDict

def lfu_cache(maxsize=128, typed=False):
    """
    Decorator to wrap a function with a memoizing callable that saves up to
    `maxsize` results based on a Least Frequently Used (LFU) algorithm.

    :param maxsize: maximum number or entries to keep
    :param typed: whether to consider types of inputs different from the return type
    :return: a memoizing callable
    """
    class LRU(cache):
        def __init__(self, maxsize):
            super().__init__()
            self.maxsize = maxsize

        def __call__(self, func):
            cache = super().__call__(func)

            @functools.wraps(cache)
            def wrapper(*args):
                key = (*args,)
                if key in self:
                    freqs = self[key]
                    freqs[0] += 1  # increment frequency
                    if freqs[1] == len(self):
                        # evict from the farthest used elements
                        self.popitem(last=False)
                else:
                    freqs = [1, len(self)]  # add to the farthest used
                    self[key] = freqs
                return cache(*args)

            return wrapper

    return LRU(maxsize)
