import os

def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    # Check if the file exists before writing
    if os.path.isfile(file_name) and not overwrite:
        raise IOError("File already exists and overwrite is disabled.")

    # Open the file with specified encoding and mode
    with open(file_name, 'wb' if isinstance(text_buffer, bytes) else 'w', encoding=encoding) as file:
        if isinstance(text_buffer, bytes):
            file.write(text_buffer)
        else:
            file.write(text_buffer.encode(encoding))

    # Return the number of bytes written
    return file.tell()
