from typing import Tuple, AnyStr, Union, Sequence
import re

def format(
        self,
        sql: AnyStr,
        params: Union[dict, Sequence[Any]],
) -> Tuple[AnyStr, Union[dict, Sequence[Any]]]:
    if not isinstance(sql, (str, bytes)):
        raise TypeError("Invalid type for SQL input")
    if not isinstance(params, (dict, list)):
        raise TypeError("Invalid type for params input")

    in_style = self.SQLParams.in_style
    if in_style == "named":
        format_func = lambda param: f":{param}"
        if isinstance(params, dict):
            formatted_params = {format_func(k): v for k, v in params.items()}
        else:
            raise TypeError("Invalid type for params in named style")
    elif in_style == "ordinal":
        format_func = lambda param: f"$p{param}"
        if isinstance(params, list):
            formatted_params = {format_func(i): v for i, v in enumerate(params)}
        else:
            raise TypeError("Invalid type for params in ordinal style")
    else:
        raise ValueError("Invalid in-style: must be 'named' or 'ordinal'")

    formatted_sql = re.sub(r"\?:([a-zA-Z0-9_]+)", lambda match: format_func(match.group(1)), sql)
    return formatted_sql, formatted_params
