def validate_version_inventories(self, version_dirs):
    if not version_dirs:
        raise ValueError("version_dirs cannot be empty")

    root_inventory = None
    content_digests = {}

    for version in version_dirs:
        try:
            # Assume each version is a directory containing an inventory
            inventory_directory = f"{version}/inventory"
            with open(inventory_directory, 'r') as inventory_file:
                inventory_content = inventory_file.read()

            # Calculate the hash of the inventory content and store it
            inventory_hash = hashlib.sha256(inventory_content.encode()).hexdigest()
            content_digests[version] = (inventory_hash,)

            # Check if this inventory is different from what's in the root inventory
            if root_inventory:
                if inventory_hash != content_digests[root_inventory][0]:
                    raise ValueError(f"Inventory for {version} is different from root inventory")

        except FileNotFoundError:
            raise ValueError(f"No inventory found for version {version}")

        except Exception as e:
            raise ValueError(f"Error processing version {version}: {e}")

    # Save the root inventory for future reference
    self.save_root_inventory(content_digests)

    self.log(f"Inventory validation passed for versions in {version_dirs}")
