import re

def deep_merge_nodes(nodes):
    merged_dict = {}
    for key, value in nodes:
        if isinstance(key, re.Pattern) and isinstance(value, dict):
            for k, v in value.items():
                merged_dict = deep_merge_with_regex(key, k, merged_dict, v)
        else:
            # If it's a non-regex key, use the last value found
            merged_dict[key] = value
    return [tuple((k, v.value)) if isinstance(v, re.Match) else (k, v) for k, v in merged_dict.items()]

def deep_merge_with_regex(key_pattern, key, merged_dict, value):
    whole_match = key_pattern.match(key)
    if not whole_match:
        return merged_dict

    prefix = key_pattern.pattern[:-len(whole_match.group(0))]
    if prefix not in merged_dict:
        merged_dict[prefix] = {}

    return deep_merge_with_regex(re.compile(prefix), key[whole_match.end():], merged_dict[prefix], value)
