        return alphabet[0]

    string = []
    while number > 0:
        digit = number % len(alphabet)
        string.append(alphabet[digit])
        number //= len(alphabet)

    if padding is not None:
        padding_size = min(padding, len(string))
        string = string[-padding_size:] if padding_size > 0 else string

    return ''.join(string[::-1])

