        command_str = ' '.join(f'[Command]::Escape("{cmd}')" if isinstance(cmd, str) else f"[Command]::Escape({str(cmd)})" for cmd in commands)

        # Construct command with arguments and options
        command = f'[Command]::Escape("{command_str}") {args}'

        # Create subprocess object
