def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    try:
        if roots is None:
            roots = set()
        output_set = set()
        stack = []

        for subject, predicate, object in graph.query(
            f"""
            SELECT DISTINCT ?subject
            WHERE {{
                ?object {prop} ?subject .
                VALUES ?subject {{
                    {{"<http://example.com/node1>"}} .
                    {{"<http://example.com/node2>"}} .
                }}
            }}
            """
        ):
            if subject not in output_set:
                output_set.add(subject)
                stack.append(subject)

        while stack:
            node = stack.pop(0)
            for _, pred, obj in graph.query(
                f"""
                SELECT DISTINCT ?object
                WHERE {{
                    ?object {prop} {node} .
                    VALUES ?node {{
                        {{"<http://example.com/node1>"}} .
                        {{"<http://example.com/node2>"}} .
                    }}
                }}
