def determineMetaclass(bases, explicit_mc=None):
    from abc import ABCMeta, abstractclassmethod
    from types import FunctionType

    def no_args():
        raise RuntimeError("no args provided")

    def uses_ABCMeta(cls):
        return issubclass(cls, ABCMeta)

    def uses_special_metaclass(cls, explicit_mc):
        if explicit_mc is not None:
            return cls is explicit_mc
        if uses_ABCMeta(cls):
            return False
        return callable(cls)

    if isinstance(bases, FunctionType):
        bases = bases.__code__.co_names

    try:
        if len(bases) == 0:
            if explicit_mc is None:
                raise AttributeError("explicit_metaclass is required when bases are empty")
            return explicit_mc
        elif len(bases) == 1:
            cls = bases[0]
            if uses_ABCMeta(cls):
                return cls
            elif uses_special_metaclass(cls, explicit_mc):
                return cls
            else:
                raise AttributeError(f"no metaclass is specified and {cls.__name__} does not inherit from ABCMeta")
        else:
            # Determine metaclass from multiple base classes
            has_ABCMeta = any(uses_ABCMeta(base) for base in bases)
            has_special_metaclass = any(uses_special_metaclass(base, explicit_mc) for base in bases)
            if not has_ABCMeta and not has_special_metaclass:
                raise AttributeError(f"no metaclass is specified and {bases} do not inherit from ABCMeta or from types.FunctionType")
