def isoparse(dt_str):
    # Split the datetime string into date and time(parts
    parts = dt_str.split('T')

    # Parse the date part
    try:
        date_part = parts[0]
        if len(date_part) == 4:
            date_part = date_part[:4] + '-' + date_part[4:]
        elif len(date_part) == 6:
            date_part = date_part[:2] + '-' + date_part[2:4] + '-' + date_part[4:]
        else:
            raise ValueError("Invalid date format")

        # Parse the time part
        time_part = parts[1] if len(parts) > 1 else '00:00'
        if len(time_part) == 1:
            time_part = "0" + time_part + "0"
        elif len(time_part) == 2:
            time_part = "0" + time_part
        elif len(time_part) == 3:
            time_part = time_part[0:1] + ":" + time_part[1:] + "0"
        elif len(time_part) == 4:
            time_part = time_part[0:2] + ":" + time_part[2:] + "0"
        elif len(time_part) == 5:
            time_part = time_part[0:1] + ":" + time_part[1:3] + "0"
        elif len(time_part) == 6:
            time_part = time_part[0:2] + ":" + time_part[2:5]
        else:
            raise ValueError("Invalid time format")

        # Split the time part into hours and minutes (optional)
        if ':' in time_part:
            hours, minutes = time_part.split(':')
        else:
            hours, minutes = time_part, '00'
        for i in range(len(hours)):
            if not hours[i].isdigit():
                raise ValueError("Invalid hour format")
        for i in range(len(minutes)):
