def _include_groups(self, parser_dict):
    if not parser_dict:
        raise ValueError("Include dict is empty")

    if not isinstance(parser_dict, dict):
        raise TypeError("Include dict is not a dictionary")

    for name, include_data in parser_dict.items():
        if not isinstance(include_data, dict):
            raise TypeError(f"Include entry for '{name}' is not a dictionary")

        if 'path' not in include_data:
            raise KeyError(f"Include entry for '{name}' missing 'path'")

        path = include_data['path']

        try:
            with open(path, 'r') as file:
                data = file.read()
                parser_dict[name] = data
        except FileNotFoundError:
            raise FileNotFoundError(f"Included file '{path}' not found")
        except Exception as e:
            raise RuntimeError(f"Error processing included file '{path}': {e}")
