    args = ['ansible-playbook']
    if playbook_path:
        args.append(playbook_path)

    if verbose is not None:
        args.append('--verbose={}'.format(verbose))
    else:
        args.append('--quiet')

    if extra_vars:
        for var, value in extra_vars.items():
            args.append('--extra-vars={}'.format(var + '=' + str(value)))

    if ansible_args:
        for key, value in ansible_args.items():
            args.append('--{}={}'.format(key, value))

    try:
        subprocess.run(args, check=True)
    except subprocess.CalledProcessError as e:
        raise SystemExit(f"ansible-playbook failed with exit code {e.returncode}: {e.output.decode('utf-8')}")
